=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (N >= 2, need not be a power of two).
// Interface: interface_spec.md. Structure: microarchitecture.md.
//   - State: one priority pointer ptr, $clog2(N) bits, synchronous active-low
//     reset to 0.
//   - Grant: combinational walk from ptr upwards, wrapping from N-1 (LAST) to 0.
//   - Update: on a rising edge with a grant (out of reset), ptr <= winner + 1,
//     wrapping at N. With no request, ptr holds.
//   - grant is not gated by reset.
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer  PW     = (N > 1) ? $clog2(N) : 1;
    localparam [31:0]   LAST32 = N - 1;
    localparam [31:0]   ONE32  = 32'd1;
    localparam [PW-1:0] LAST   = LAST32[PW-1:0];
    localparam [PW-1:0] ONE    = ONE32[PW-1:0];
    localparam [N-1:0]  GRANT0 = {{(N-1){1'b0}}, 1'b1};

    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_next;
    reg [PW-1:0] winner;
    reg [PW-1:0] idx;
    reg          found;
    integer      k;

    // Wrapping priority search from ptr. Every output has a default: no latch.
    always @* begin
        found  = 1'b0;
        winner = {PW{1'b0}};
        idx    = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[idx]) begin
                found  = 1'b1;
                winner = idx;
            end
            if (idx == LAST) idx = {PW{1'b0}};
            else             idx = idx + ONE;
        end
        if (found) grant = GRANT0 << winner;
        else       grant = {N{1'b0}};
    end

    // Next pointer: one past the winner, wrapping explicitly at N.
    always @* begin
        ptr_next = ptr;
        if (found) begin
            if (winner == LAST) ptr_next = {PW{1'b0}};
            else                ptr_next = winner + ONE;
        end
    end

    // Pointer register: reset value and load only.
    always @(posedge clk) begin
        if (!rst_n) ptr <= {PW{1'b0}};
        else        ptr <= ptr_next;
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (interface_spec.md section 6).
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active in the first cycle.
    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    wire [31:0] f_ptr   = {{(32-PW){1'b0}}, ptr};
    wire [31:0] f_win   = {{(32-PW){1'b0}}, winner};
    wire [31:0] f_d_win = (f_win >= f_ptr) ? (f_win - f_ptr) : (f_win + N - f_ptr);

    always @(*) begin
        if (f_past_valid) begin
            // Pointer in range.
            assert (ptr <= LAST);
            // One-hot or zero.
            assert ((grant & (grant - GRANT0)) == {N{1'b0}});
            // Only to a requester.
            assert ((grant & ~req) == {N{1'b0}});
            // Work conserving.
            assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            // The grant names the winner.
            assert (found == (grant != {N{1'b0}}));
            if (found) begin
                assert (req[winner]);
                assert (grant == (GRANT0 << winner));
            end
        end
    end

    // Pointer update rule and reset value.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (ptr == {PW{1'b0}});
            end else if ($past(found)) begin
                if ($past(winner) == LAST) assert (ptr == {PW{1'b0}});
                else                       assert (ptr == $past(winner) + ONE);
            end else begin
                assert (ptr == $past(ptr));
            end
        end
    end

    genvar gi;
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_formal
            reg  [31:0] f_wait;
            wire [31:0] f_idx  = gi;
            wire [31:0] f_dist = (f_idx >= f_ptr) ? (f_idx - f_ptr)
                                                  : (f_idx + N - f_ptr);

            initial f_wait = 32'd0;

            // Cycles requester gi has waited with its request held.
            always @(posedge clk) begin
                if (!rst_n || !req[gi] || grant[gi]) f_wait <= 32'd0;
                else                                 f_wait <= f_wait + 32'd1;
            end

            always @(*) begin
                if (f_past_valid) begin
                    // Round-robin order: nobody between the pointer and the winner.
                    if (found && (f_dist < f_d_win)) assert (!req[gi]);
                    // Starvation bound, and its induction invariant.
                    assert (f_wait <= N - 1);
                    assert (f_wait + f_dist <= N - 1);
                end
            end

            always @(posedge clk) begin
                if (f_past_valid && rst_n) begin
                    cover (grant[gi]);
                    cover (f_wait == N - 1);
                end
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover (req == {N{1'b1}});
            cover (req == {N{1'b0}});
        end
        if (f_past_valid && $past(rst_n)) begin
            cover (($past(ptr) == LAST) && (ptr == {PW{1'b0}}));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===

