// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter: two lanes, N = 4 and N = 5, each
// checked every rising edge against a reference pointer model, with
// per-requester wait counters (fairness) and coverage counters.
`default_nettype none

module rr_arbiter_tb_lane #(
    parameter integer N    = 4,
    parameter [31:0]  SEED = 32'h0000_0001
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [2:0]  phase,
    input  wire        done,
    output wire [31:0] passed_o,
    output wire [31:0] failed_o
);
    localparam [2:0] P_IDLE   = 3'd0;
    localparam [2:0] P_ALONE  = 3'd1;
    localparam [2:0] P_ALL    = 3'd2;
    localparam [2:0] P_HELD   = 3'd3;
    localparam [2:0] P_RANDOM = 3'd4;

    localparam [N-1:0] ONE_N  = {{(N-1){1'b0}}, 1'b1};
    localparam [N-1:0] ZERO_N = {N{1'b0}};
    localparam [N-1:0] ALL_N  = {N{1'b1}};
    localparam [N-1:0] HOLD_N = {1'b1, {(N-1){1'b0}}};

    reg  [N-1:0] req = {N{1'b0}};
    wire [N-1:0] grant;
    wire [N-1:0] waiting = req & ~grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    integer passed = 0;
    integer failed = 0;
    assign passed_o = passed;
    assign failed_o = failed;

    // ------------------------------------------------------------------
    // Stimulus, driven on the falling edge.
    // ------------------------------------------------------------------
    reg [31:0] rnd = SEED;
    integer    cnt = 0;
    integer    sel = 0;

    always @(negedge clk) begin
        rnd = rnd ^ (rnd << 13);
        rnd = rnd ^ (rnd >> 17);
        rnd = rnd ^ (rnd << 5);
        cnt = cnt + 1;
        sel = (cnt / 2) % N;
        case (phase)
            P_ALONE:  req = ONE_N << sel;
            P_ALL:    req = ALL_N;
            P_HELD:   req = rnd[N-1:0] | HOLD_N;
            P_RANDOM: req = rnd[N-1:0];
            default:  req = ZERO_N;
        endcase
    end

    // ------------------------------------------------------------------
    // Reference model and checks, on the rising edge (pre-update values).
    // ------------------------------------------------------------------
    integer     mptr      = 0;
    reg         mvalid    = 1'b0;
    integer     k         = 0;
    integer     idx       = 0;
    integer     exp_win   = 0;
    reg         exp_found = 1'b0;
    reg [N-1:0] exp_grant = {N{1'b0}};
    reg [N-1:0] prev_req  = {N{1'b0}};
    integer     waitc [0:N-1];
    integer     max_wait  = 0;
    integer     cov_none  = 0;
    integer     cov_all   = 0;
    integer     cov_held  = 0;
    integer     cov_rst   = 0;
    integer     cov_wrap  = 0;
    reg [N-1:0] cov_alone = {N{1'b0}};
    reg         final_done = 1'b0;

    // Coverage items:
    //   1 no requests, 2 each requester alone, 3 everyone requesting (>= 2N
    //   cycles), 4 held request among changing others, 5 longest fair wait
    //   (N-1), 6 reset during traffic, 7 pointer wrap (winner N-1).
    task check_cov;
        input         ok;
        input integer id;
        begin
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("rr_arbiter N=%0d: coverage item %0d not reached", N, id);
            end
        end
    endtask

    always @(posedge clk) begin
        if (mvalid) begin
            // Expected grant: first requester at or after the model pointer.
            exp_found = 1'b0;
            exp_win   = 0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (mptr + k) % N;
                if (!exp_found && (((req >> idx) & ONE_N) != ZERO_N)) begin
                    exp_found = 1'b1;
                    exp_win   = idx;
                end
            end
            exp_grant = ZERO_N;
            if (exp_found) exp_grant = ONE_N << exp_win;

            if (grant === exp_grant) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("rr_arbiter N=%0d: grant %b, expected %b (req %b, reference pointer %0d)",
                       N, grant, exp_grant, req, mptr);
            end

            // Fairness: a held request waits at most N-1 cycles.
            for (k = 0; k < N; k = k + 1) begin
                if (!rst_n || (((waiting >> k) & ONE_N) == ZERO_N)) waitc[k] = 0;
                else                                                waitc[k] = waitc[k] + 1;
                if (waitc[k] > N - 1) begin
                    failed = failed + 1;
                    $error("rr_arbiter N=%0d: requester %0d has waited %0d cycles (bound %0d)",
                           N, k, waitc[k], N - 1);
                end else if (rst_n && (((req >> k) & ONE_N) != ZERO_N)) begin
                    passed = passed + 1;
                end
                if (waitc[k] > max_wait) max_wait = waitc[k];
            end

            // Coverage.
            if (rst_n) begin
                if (req == ZERO_N) cov_none = cov_none + 1;
                if (req == ALL_N)  cov_all  = cov_all + 1;
                for (k = 0; k < N; k = k + 1) begin
                    if (req == (ONE_N << k)) cov_alone = cov_alone | (ONE_N << k);
                end
                if (((req & prev_req) != ZERO_N) && ((req ^ prev_req) != ZERO_N))
                    cov_held = cov_held + 1;
                if (exp_found && (exp_win == N - 1)) cov_wrap = cov_wrap + 1;
            end else if (req != ZERO_N) begin
                cov_rst = cov_rst + 1;
            end

            // Reference pointer update.
            if (!rst_n)         mptr = 0;
            else if (exp_found) mptr = (exp_win + 1) % N;
        end

        if (!rst_n) begin
            mvalid = 1'b1;
            mptr   = 0;
            for (k = 0; k < N; k = k + 1) waitc[k] = 0;
        end

        prev_req = req;

        if (done && !final_done) begin
            final_done = 1'b1;
            check_cov(cov_none != 0,        1);
            check_cov(cov_alone == ALL_N,   2);
            check_cov(cov_all >= 2 * N,     3);
            check_cov(cov_held != 0,        4);
            check_cov(max_wait == N - 1,    5);
            check_cov(cov_rst != 0,         6);
            check_cov(cov_wrap != 0,        7);
        end
    end
endmodule

module rr_arbiter_tb;
    localparam [2:0] P_IDLE   = 3'd0;
    localparam [2:0] P_ALONE  = 3'd1;
    localparam [2:0] P_ALL    = 3'd2;
    localparam [2:0] P_HELD   = 3'd3;
    localparam [2:0] P_RANDOM = 3'd4;

    reg            clk   = 1'b0;
    reg            rst_n = 1'b0;
    reg  [2:0]     phase = 3'd0;
    reg            done  = 1'b0;
    reg  [8*64-1:0] nonce = {(8*64){1'b0}};
    wire [31:0]    passed4;
    wire [31:0]    failed4;
    wire [31:0]    passed5;
    wire [31:0]    failed5;
    integer        passed = 0;
    integer        failed = 0;

    always #5 clk = ~clk;

    rr_arbiter_tb_lane #(.N(4), .SEED(32'h1234_5678)) lane4 (
        .clk      (clk),
        .rst_n    (rst_n),
        .phase    (phase),
        .done     (done),
        .passed_o (passed4),
        .failed_o (failed4)
    );

    rr_arbiter_tb_lane #(.N(5), .SEED(32'h9E37_79B9)) lane5 (
        .clk      (clk),
        .rst_n    (rst_n),
        .phase    (phase),
        .done     (done),
        .passed_o (passed5),
        .failed_o (failed5)
    );

    // Wait n rising edges, then step just past the edge.
    task cycles;
        input integer n;
        begin
            repeat (n) @(posedge clk);
            #1;
        end
    endtask

    initial begin
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = {(8*64){1'b0}};
        end

        rst_n = 1'b0;
        phase = P_IDLE;
        cycles(3);
        rst_n = 1'b1;              // no requests
        cycles(4);
        phase = P_ALONE;           // each requester alone
        cycles(24);
        phase = P_ALL;             // reset with everyone requesting ...
        rst_n = 1'b0;
        cycles(2);
        rst_n = 1'b1;              // ... then strict rotation from pointer 0
        cycles(20);
        phase = P_HELD;            // requester N-1 held among changing others
        cycles(40);
        phase = P_RANDOM;          // random subsets, drops and raises
        cycles(50);
        rst_n = 1'b0;              // reset during traffic
        cycles(3);
        rst_n = 1'b1;
        cycles(50);
        phase = P_IDLE;
        cycles(2);
        done = 1'b1;
        cycles(2);

        passed = passed4 + passed5;
        failed = failed4 + failed5;
        if (passed4 == 32'd0) begin
            failed = failed + 1;
            $error("rr_arbiter_tb: lane N=4 recorded no passing check");
        end
        if (passed5 == 32'd0) begin
            failed = failed + 1;
            $error("rr_arbiter_tb: lane N=5 recorded no passing check");
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule

`default_nettype wire
